package org.hl7.fhir.common.js;

import static org.junit.jupiter.api.Assertions.*;

import java.io.IOException;
import java.io.InputStream;
import java.nio.charset.StandardCharsets;
import java.nio.file.*;
import java.util.*;
import java.util.stream.Stream;
import org.junit.jupiter.api.Assumptions;
import org.junit.jupiter.api.Test;

/**
 * Oracle tests for the JS-semantics JSON layer. vectors.json is generated by node (scripts/oracle/js-vectors.js);
 * the round-trip test re-serializes every JSON file TS SUSHI 3.21.1 wrote for real IGs (reference outputs on the VM).
 */
class JsonTest {
  @SuppressWarnings("unchecked")
  static Map<String, Object> vectors() throws IOException {
    try (InputStream in = JsonTest.class.getResourceAsStream("/js/vectors.json")) {
      return (Map<String, Object>) Json.parse(new String(in.readAllBytes(), StandardCharsets.UTF_8));
    }
  }

  @SuppressWarnings("unchecked")
  @Test void numberToStringMatchesV8() throws IOException {
    List<Object> nums = (List<Object>) vectors().get("numbers");
    int n = 0;
    for (Object o : nums) {
      List<Object> v = (List<Object>) o;
      double d = Double.parseDouble((String) v.get(0));
      assertEquals(v.get(0), JsNumber.toString(d), "toString of " + v.get(0));
      assertEquals(v.get(1), Json.stringify(d), "stringify of " + v.get(0));
      n++;
    }
    assertTrue(n > 2000);
    assertEquals("0", Json.stringify(-0.0));
    assertEquals("null", Json.stringify(Double.NaN));
  }

  /** The digits worked out without Double.toString (used on JDK 17/18) are V8's, on any JDK */
  @SuppressWarnings("unchecked")
  @Test void shortestDigitsMatchV8() throws IOException {
    for (Object o : (List<Object>) vectors().get("numbers")) {
      String js = (String) ((List<Object>) o).get(0);
      double d = Math.abs(Double.parseDouble(js));
      if (d == 0 || Double.isNaN(d) || Double.isInfinite(d)) continue;
      java.math.BigDecimal want = new java.math.BigDecimal(js.startsWith("-") ? js.substring(1) : js).stripTrailingZeros();
      java.math.BigDecimal got = JsNumber.shortestDigits(d);
      assertEquals(want.unscaledValue() + "e" + -want.scale(), got.unscaledValue() + "e" + -got.scale(), js);
    }
    // and on JDK 19+, where Double.toString is the shortest, the same digits for random doubles
    if (Runtime.version().feature() >= 19) {
      java.util.Random rnd = new java.util.Random(42);
      for (int i = 0; i < 200_000; i++) {
        double d = i % 2 == 0 ? Double.longBitsToDouble(rnd.nextLong() & Long.MAX_VALUE) : rnd.nextDouble() * Math.pow(10, rnd.nextInt(40) - 20);
        if (d == 0 || Double.isNaN(d) || Double.isInfinite(d)) continue;
        java.math.BigDecimal want = new java.math.BigDecimal(Double.toString(d)).stripTrailingZeros();
        java.math.BigDecimal got = JsNumber.shortestDigits(d);
        if (want.precision() == 2 && got.precision() == 1) continue; // Double.toString's 2-digit floor (5e-324 & co)
        assertEquals(want, got, "digits of " + Double.toString(d));
      }
    }
  }

  @SuppressWarnings("unchecked")
  @Test void stringQuotingMatchesV8() throws IOException {
    for (Object o : (List<Object>) vectors().get("strings")) {
      List<Object> v = (List<Object>) o;
      StringBuilder s = new StringBuilder();
      for (Object c : (List<Object>) v.get(0)) s.append((char) ((Double) c).intValue());
      assertEquals(v.get(1), Json.stringify(s.toString()));
    }
  }

  @SuppressWarnings("unchecked")
  @Test void prettyPrintingAndKeyOrderMatchV8() throws IOException {
    for (Object o : (List<Object>) vectors().get("pretty")) {
      List<Object> v = (List<Object>) o;
      Object value = Json.parse((String) v.get(0));
      assertEquals(v.get(0), Json.stringify(value));
      assertEquals(v.get(1), Json.stringify(value, 2));
    }
    for (Object o : (List<Object>) vectors().get("parsed")) {
      List<Object> v = (List<Object>) o;
      assertEquals(v.get(1), Json.stringify(Json.parse((String) v.get(0)), 2), "parse of " + v.get(0));
    }
  }

  @Test void undefinedIsOmittedFromObjectsAndNullInArrays() {
    JsObject o = new JsObject().with("a", Js.UNDEFINED).with("b", new ArrayList<>(Arrays.asList(Js.UNDEFINED, 1.0)));
    assertEquals("{\"b\":[null,1]}", Json.stringify(o));
    assertNull(Json.stringify(Js.UNDEFINED));
    JsonSerializable ts = () -> new JsObject().with("x", 1L);
    assertEquals("{\n  \"y\": {\n    \"x\": 1\n  }\n}\n", Json.outputJson(new JsObject().with("y", ts)));
  }

  @Test void lodashSemantics() {
    assertTrue(Js.isEqual(Json.parse("{\"a\":[1,{\"b\":0}]}"), Json.parse("{\"a\":[1.0,{\"b\":-0}]}")));
    assertFalse(Js.isEqual(new JsObject().with("a", Js.UNDEFINED), new JsObject()));
    Object orig = Json.parse("{\"a\":[1,{\"b\":2}]}");
    Object copy = Js.cloneDeep(orig);
    assertNotSame(orig, copy);
    assertTrue(Js.isEqual(orig, copy));
    assertEquals(List.of("1", "2", "b", "01"), Js.ownKeys(new JsObject().with("b", 1).with("2", 1).with("01", 1).with("1", 1)));
  }

  /** parse + outputJson must reproduce every fsh-generated JSON file byte for byte. */
  @Test void roundTripsRealSushiOutput() throws IOException {
    // opt-in: TS SUSHI's recorded output for the reference IGs is not in the repository
    String vm = System.getProperty("sushi.vmdata", "");
    Assumptions.assumeFalse(vm.isEmpty(), "opt-in: run with -Dsushi.vmdata=<data root> (reference outputs under sushi-port/ref)");
    Path ref = Paths.get(vm, "sushi-port", "ref");
    Assumptions.assumeTrue(Files.isDirectory(ref), "opt-in: reference outputs not found at " + ref);
    int files = 0;
    List<String> bad = new ArrayList<>();
    try (Stream<Path> s = Files.walk(ref)) {
      for (Path p : s.filter(f -> f.toString().endsWith(".json")).sorted().toList()) {
        String text = Files.readString(p, StandardCharsets.UTF_8);
        if (!Json.outputJson(Json.parse(text)).equals(text)) bad.add(p.toString());
        files++;
      }
    }
    System.out.println("JsonTest.roundTripsRealSushiOutput: " + files + " files, " + bad.size() + " differ");
    assertTrue(files > 100);
    assertEquals(List.of(), bad);
  }
}
